"""Pinned diagnostic runs. New names only; GPU work is serial; Berlin deadline enforced."""
from datetime import datetime, time as daytime
from zoneinfo import ZoneInfo
import hashlib,json,os,shlex,subprocess,sys,time
from pathlib import Path
ROOT=Path('/home/sebastian/Development/gem16gb')
OUT=Path(__file__).resolve().parent
BIN=ROOT/'build/Linux/blackwell-release/bin'
PATHS=json.loads((OUT/'paths.json').read_text())

def guard(seconds=180):
 now=datetime.now(ZoneInfo('Europe/Berlin'))
 end=datetime.combine(now.date(),daytime(22,55),tzinfo=now.tzinfo)
 if (end-now).total_seconds() < seconds+300: raise RuntimeError('Berlin wrap-up deadline: do not start this operation')

def record(name,args,timeout=300,env=None):
 guard(timeout)
 path=OUT/(name+'.command.json')
 if path.exists():
  assert json.loads(path.read_text())==args,name
  rows=[json.loads(line) for line in (OUT/'executions.jsonl').read_text().splitlines()]
  assert any(r['name']==name and r['returncode']==0 for r in rows),name
  return OUT/(name+'.stdout.log')
 path.write_text(json.dumps(args,indent=2)+'\n')
 start=time.time()
 with (OUT/(name+'.stdout.log')).open('x') as stdout,(OUT/(name+'.stderr.log')).open('x') as stderr:
  p=subprocess.run(args,cwd=ROOT,stdout=stdout,stderr=stderr,env=env,timeout=timeout)
 row={'name':name,'command':args,'returncode':p.returncode,'start_unix':start,'end_unix':time.time(),'berlin_end':datetime.now(ZoneInfo('Europe/Berlin')).isoformat(),'test_environment':({k:v for k,v in env.items() if k in ['GEM16_12B_MODEL','GEM16_M22_RAW_DIR','LD_PRELOAD','GEM16_AUDIT_SELECTIONS_JSON','GEM16_AUDIT_PROPOSALS_JSON']} if env else {})}
 with (OUT/'executions.jsonl').open('a') as f:f.write(json.dumps(row)+'\n')
 print(name,p.returncode,round(row['end_unix']-start,2),'s',flush=True)
 if p.returncode:raise RuntimeError(name+' failed: '+str(p.returncode))
 return OUT/(name+'.stdout.log')

def base(mode='ordinary',n=8,model=None):
 args=[str(BIN/'gem16-run'),'--model',model or PATHS['target'],'--input-token-ids-file',str(OUT/'prompt.ids'),'--kv-cache','fp8','--max-context','17519','--greedy','--suppress-token-ids','1,50,106,258882,258883','--max-tokens',str(n)]
 if mode=='d2':args+=['--assistant-model',PATHS['assistant'],'--mtp-draft-tokens','2']
 return args

def validate(path,n):
 d=json.loads(path.read_text()); assert len(d['output_token_ids'])==n
 assert d['fallbacks']==0 and d['token_loop_allocations'] is False
 return d

def checks():
 for name,regex in [('cuda-focused','^gem16-cuda-(conditional-graph|trellis35|attention-reference|nvfp4-consumption)$'),('cuda-full','^gem16-cuda$'),('host','^gem16-(unit|responses-allocation)$'),('12b-product-qualified','^gem16-12b-m22-product$')]:
  environment=None
  if name=='12b-product-qualified':
   environment=os.environ.copy();environment.update(GEM16_12B_MODEL=PATHS['12b_target'],GEM16_M22_RAW_DIR=str(OUT/'12b-product-fixture'))
  p=record('check-'+name,['ctest','--test-dir',str(BIN.parent),'--output-on-failure','-R',regex],600,environment)
  s=p.read_text();assert '100% tests passed' in s and 'Not Run' not in s and 'Skipped' not in s
 for name,args in [('conditional',[str(BIN/'gem16-cuda-conditional-graph-tests')]),('ring',[str(BIN/'gem16-cuda-tests'),'mtp-control']),('trellis-d2',base('d2',8))]:
  p=record('memcheck-'+name,['compute-sanitizer','--tool','memcheck','--error-exitcode','99',*args],600)
  assert 'ERROR SUMMARY: 0 errors' in p.read_text()+(OUT/('memcheck-'+name+'.stderr.log')).read_text()
 record('check-python',['python','-m','unittest','tests.python.test_benchmark_wikipedia_workload','tests.python.test_benchmark_gemma4_26b_wp8_text'],60)
 for profile in ['12b','nvfp4']:
  observed=[]
  for mode in ['ordinary','d2']:
   args=base(mode,64,PATHS['12b_target' if profile=='12b' else 'nvfp4'])
   start=args.index('--input-token-ids-file');args[start:start+2]=['--input-token-ids','2,105,2364,107,40654,607,7121,506,3658,3730,236761,106,107,105,4368,107,100,45518,107,101']
   if profile=='12b':
    args[args.index('--max-context')+1]='4096'
    if mode=='d2':args[args.index('--assistant-model')+1]=PATHS['12b_assistant']
   p=record('regression-'+profile+'-'+mode,args,240);observed.append(validate(p,64)['output_token_ids'])
  assert observed[0]==observed[1],profile
  print('PARITY',profile,'64 tokens',flush=True)

def probes():
 outputs={}
 for n in [8,64]:
  for mode in ['ordinary','d2']:
   p=record(mode+'-'+str(n),base(mode,n),180)
   outputs[mode,n]=validate(p,n)['output_token_ids']
  assert outputs['ordinary',n]==outputs['d2',n]
 prior=json.loads((ROOT/'benchmarks/results/2026-10-10/c01789a2/d2-graph-fix/gem16-ordinary.json').read_text())['representative_output_token_ids']
 assert outputs['ordinary',64]==prior[:64]
 print('PARITY 8/64 and historical fixed fixture prefixes',flush=True)

def profiles(n=8):
 for mode in ['ordinary','d2']:
  name=mode+'-'+str(n)+'-trace'
  output=OUT/(name+'.json')
  args=base(mode,n)+['--cuda-profile-phase','decode']
  profile=['nsys','profile','--trace=cuda,nvtx,osrt','--sample=none','--cpuctxsw=none','--cuda-graph-trace=node:nvtx-precapture','--capture-range=cudaProfilerApi','--capture-range-end=stop','-o',str(OUT/name),'sh','-c',shlex.join(args)+' > '+shlex.quote(str(output))]
  record(name,profile,600)
  d=validate(output,n)
  reference=json.loads((OUT/(mode+'-'+str(n)+'.stdout.log')).read_text()) if (OUT/(mode+'-'+str(n)+'.stdout.log')).exists() else json.loads((ROOT/'benchmarks/results/2026-10-10/c01789a2/d2-graph-fix/gem16-ordinary.json').read_text())
  expected=reference.get('output_token_ids',reference.get('representative_output_token_ids'))
  assert d['output_token_ids']==expected[:n]
  record(name+'-export',['nsys','export','--type','sqlite','--output',str(OUT/(name+'.sqlite')),str(OUT/(name+'.nsys-rep'))],300)
  for report in ['cuda_gpu_kern_sum','cuda_api_sum','nvtx_gpu_proj_sum','nvtx_gpu_proj_trace']:
   record(name+'-'+report+'-sqlite',['nsys','stats','--report',report,'--format','csv',str(OUT/(name+'.sqlite'))],300)

if __name__=='__main__':
 mode=sys.argv[1]
 if mode=='checks': checks()
 elif mode=='probes':probes()
 elif mode=='profiles':profiles(int(sys.argv[2]) if len(sys.argv)>2 else 8)
 else:raise RuntimeError('unknown phase')

