// Observe the existing readbacks only. No additional CUDA calls or allocations
// in the inference loop; fixed host arrays and file output at process exit.
#include <cuda_runtime_api.h>
#include <dlfcn.h>
#include <array>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
namespace {
constexpr unsigned kCapacity=17519;
struct Pair{unsigned predicted,selected;};
std::array<Pair,kCapacity> records{};unsigned count=0;
void* pending_status=nullptr;void* pending_selected=nullptr;
unsigned predicted=0;bool valid=false;char path[4096]{};
using CopyAsync=cudaError_t(*)(void*,const void*,std::size_t,cudaMemcpyKind,cudaStream_t);
using Sync=cudaError_t(*)(cudaStream_t);
CopyAsync real_copy=nullptr;Sync real_sync=nullptr;
void save(){
 if(!path[0])return;FILE* f=std::fopen(path,"wx");if(!f)return;
 std::fprintf(f,"{\"diagnostic_only\":true,\"count\":%u,\"pairs\":[",count);
 for(unsigned i=0;i<count;++i)std::fprintf(f,"%s[%u,%u]",i?",":"",records[i].predicted,records[i].selected);
 std::fputs("]}\n",f);std::fclose(f);
}
__attribute__((constructor)) void initialize(){
 const char* output=std::getenv("GEM16_AUDIT_SELECTIONS_JSON");
 if(output && std::strlen(output)<sizeof(path)){std::strcpy(path,output);std::atexit(save);}
 real_copy=reinterpret_cast<CopyAsync>(dlsym(RTLD_NEXT,"cudaMemcpyAsync"));
 real_sync=reinterpret_cast<Sync>(dlsym(RTLD_NEXT,"cudaStreamSynchronize"));
}
}
extern "C" cudaError_t cudaMemcpyAsync(void* dst,const void* src,std::size_t bytes,cudaMemcpyKind kind,cudaStream_t stream){
 const cudaError_t result=real_copy(dst,src,bytes,kind,stream);
 if(path[0] && result==cudaSuccess && kind==cudaMemcpyDeviceToHost){
  if(bytes==16)pending_status=dst;
  else if(bytes==4)pending_selected=dst;
 }
 return result;
}
extern "C" cudaError_t cudaStreamSynchronize(cudaStream_t stream){
 const cudaError_t result=real_sync(stream);
 if(result==cudaSuccess && path[0]){
  if(pending_status){
   std::array<unsigned,4> status{};std::memcpy(status.data(),pending_status,16);
   valid=status[0]<262144 && status[2]!=0 && status[3]!=0;predicted=status[0];pending_status=nullptr;
  }
  if(pending_selected){
   unsigned selected=0;std::memcpy(&selected,pending_selected,4);
   if(valid && count<kCapacity)records[count++]={predicted,selected};
   pending_selected=nullptr;valid=false;
  }
 }
 return result;
}

